html:
{%- set g = get_supply_label_data(doc.name) -%}
{%- set n = (doc.item_code or "") | length -%}
{%- set code_pt = 17 if n <= 13 else (14 if n <= 17 else 11) -%}
<style>
	.print-format { page-width: 101.6mm; page-height: 50.8mm; margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; padding: 0 !important; width: 101.6mm !important; max-width: 101.6mm !important; min-height: 0 !important; }
	.sl, .sl div { box-sizing: border-box; }
	.sl { position: relative; width: 101.6mm; height: 50.6mm; overflow: hidden; font-family: Arial, Helvetica, sans-serif; color: #000; background: #fff; page-break-after: always; }
	.sl .qr { position: absolute; left: 3mm; top: 4.3mm; width: 42mm; height: 42mm; }
	.sl .txt { position: absolute; left: 48mm; top: 4mm; width: 50.6mm; height: 42.8mm; overflow: hidden; }
	.sl .code { font-size: 17pt; font-weight: bold; line-height: 1.05; word-wrap: break-word; }
	.sl .name { font-size: 10.5pt; line-height: 1.15; margin-top: 2mm; max-height: 25mm; overflow: hidden; }
	.sl .meta { position: absolute; left: 0; bottom: 0; width: 50.6mm; font-size: 8pt; line-height: 1.2; border-top: 0.3mm solid #000; padding-top: 1mm; }
</style>
<div class="sl">
	<img class="qr" src="{{ g.qr }}" alt="{{ g.barcode }}">
	<div class="txt">
		<div class="code" style="font-size:{{ code_pt }}pt">{{ doc.item_code }}</div>
		<div class="name">{{ doc.item_name if doc.item_name != doc.item_code else (doc.description or "") | striptags | truncate(110) }}</div>
		<div class="meta">
			{{ _("UOM") }}: {{ doc.stock_uom }}{% if doc.item_group %} &nbsp;|&nbsp; {{ doc.item_group }}{% endif %}<br>
			{{ _("Scan to issue, count or reorder") }}{% if g.barcode != doc.item_code %}<br>{{ g.barcode }}{% endif %}
		</div>
	</div>
</div>
